def select_model(task_type: str) -> tuple:
    """
    Dynamically select the best model based on task type.
    Returns: (provider, model_id)
    """
    model_map = {
        'reasoning': ('cerebras', 'gpt-oss-120b'),
        'synthesis': ('bedrock', 'anthropic.claude-4-5-sonnet-v2:0'),
        'structured_extraction': ('cerebras', 'qwen-3-32b'),
        'fast_query': ('cerebras', 'llama3.1-8b'),
        'final_report': ('bedrock', 'anthropic.claude-4-5-sonnet-v2:0'),
        'creative': ('xai', 'grok-beta')
    }
    return model_map.get(task_type, ('cerebras', 'gpt-oss-120b'))


def call_llm(provider: str, model: str, messages: List[Dict], tools: Optional[List] = None, max_tokens: int = 4000) -> Dict:
    """
    Universal LLM caller supporting multiple providers.
    """
    try:
        if provider == 'cerebras':
            response = cerebras_client.chat.completions.create(
                model=model,
                messages=messages,
                max_tokens=max_tokens,
                tools=tools if tools else None,
                temperature=0.7
            )
            return {
                'content': response.choices[0].message.content,
                'tool_calls': getattr(response.choices[0].message, 'tool_calls', None)
            }

        elif provider == 'bedrock':
            # Claude Messages API format
            formatted_messages = []
            system_prompt = ""

            for msg in messages:
                if msg['role'] == 'system':
                    system_prompt = msg['content']
                else:
                    formatted_messages.append({
                        'role': msg['role'],
                        'content': msg['content']
                    })

            body = {
                'anthropic_version': 'bedrock-2023-05-31',
                'max_tokens': max_tokens,
                'messages': formatted_messages,
                'temperature': 0.7
            }

            if system_prompt:
                body['system'] = system_prompt

            response = bedrock_client.invoke_model(
                modelId=model,
                body=json.dumps(body),
                contentType='application/json'
            )

            response_body = json.loads(response['body'].read())
            return {
                'content': response_body['content'][0]['text'],
                'tool_calls': None
            }

        elif provider == 'xai':
            response = xai_client.chat.completions.create(
                model=model,
                messages=messages,
                max_tokens=max_tokens,
                temperature=0.7
            )
            return {
                'content': response.choices[0].message.content,
                'tool_calls': None
            }

    except Exception as e:
        print(f"LLM call error ({provider}/{model}): {e}")
        return {'content': f"Error: {str(e)}", 'tool_calls': None}


