def exa_search(query: str, category: Optional[str] = None, num_results: int = 10, 
               start_date: Optional[str] = None, end_date: Optional[str] = None) -> Dict:
    """
    Exa AI search tool for finding relevant web content.
    """
    try:
        params = {
            'query': query,
            'num_results': num_results,
            'type': 'auto'
        }

        if category:
            params['category'] = category
        if start_date:
            params['start_published_date'] = start_date
        if end_date:
            params['end_published_date'] = end_date

        result = exa_client.search(**params)

        return {
            'success': True,
            'results': [
                {
                    'url': r.url,
                    'title': r.title,
                    'published_date': r.published_date,
                    'id': r.id
                }
                for r in result.results
            ]
        }
    except Exception as e:
        return {'success': False, 'error': str(e)}


def exa_find_similar(url: str, num_results: int = 10) -> Dict:
    """
    Find similar URLs using Exa AI.
    """
    try:
        result = exa_client.find_similar(
            url=url,
            num_results=num_results,
            exclude_source_domain=True
        )

        return {
            'success': True,
            'results': [
                {
                    'url': r.url,
                    'title': r.title,
                    'published_date': r.published_date
                }
                for r in result.results
            ]
        }
    except Exception as e:
        return {'success': False, 'error': str(e)}


def exa_get_contents(urls: List[str], subpages: int = 0) -> Dict:
    """
    Get full content from URLs with optional subpage crawling.
    """
    try:
        result = exa_client.get_contents(
            ids=urls,
            text=True,
            highlights=True,
            livecrawl='preferred',
            subpages=subpages
        )

        return {
            'success': True,
            'contents': [
                {
                    'url': r.url,
                    'title': r.title,
                    'text': r.text[:5000] if hasattr(r, 'text') else '',  # Limit text size
                    'highlights': r.highlights if hasattr(r, 'highlights') else []
                }
                for r in result.results
            ]
        }
    except Exception as e:
        return {'success': False, 'error': str(e)}


def exa_extract_structured(query: str, schema: Dict) -> Dict:
    """
    Extract structured data using Exa AI with custom schema.
    """
    try:
        result = exa_client.search_and_contents(
            query=query,
            summary={
                'query': query,
                'schema': schema
            },
            num_results=5
        )

        return {
            'success': True,
            'structured_data': [
                json.loads(r.summary) if hasattr(r, 'summary') else {}
                for r in result.results
            ]
        }
    except Exception as e:
        return {'success': False, 'error': str(e)}


