# ============================================================================
# KNOWLEDGE GRAPH & MEMORY
# ============================================================================

class KnowledgeGraph:
    """In-memory knowledge graph for research."""

    def __init__(self):
        self.entities = {}
        self.relations = []
        self.sources = set()

    def add_entity(self, name: str, entity_type: str, properties: Dict):
        """Add or update an entity."""
        if name not in self.entities:
            self.entities[name] = {
                'type': entity_type,
                'properties': properties,
                'mentions': 1
            }
        else:
            self.entities[name]['mentions'] += 1
            self.entities[name]['properties'].update(properties)

    def add_relation(self, subject: str, predicate: str, object_: str, source: str):
        """Add a relation between entities."""
        self.relations.append({
            'subject': subject,
            'predicate': predicate,
            'object': object_,
            'source': source
        })
        self.sources.add(source)

    def to_dict(self):
        """Export knowledge graph as dictionary."""
        return {
            'entities': self.entities,
            'relations': self.relations,
            'sources': list(self.sources),
            'entity_count': len(self.entities),
            'relation_count': len(self.relations)
        }

    def to_text(self) -> str:
        """Convert knowledge graph to text format for LLM consumption."""
        text = "# KNOWLEDGE GRAPH\n\n"
        text += f"## Entities ({len(self.entities)})\n\n"

        for name, data in list(self.entities.items())[:50]:  # Limit for context
            text += f"- **{name}** ({data['type']}): "
            text += ", ".join([f"{k}={v}" for k, v in list(data['properties'].items())[:3]])
            text += f" [mentions: {data['mentions']}]\n"

        text += f"\n## Relations ({len(self.relations)})\n\n"
        for rel in self.relations[:100]:  # Limit for context
            text += f"- {rel['subject']} → {rel['predicate']} → {rel['object']} (source: {rel['source']})\n"

        text += f"\n## Sources ({len(self.sources)})\n\n"
        for source in list(self.sources)[:20]:
            text += f"- {source}\n"

        return text


# ============================================================================
# ORCHESTRATOR (COGNITIVE CORE)
# ============================================================================

class ResearchOrchestrator:
    """Main cognitive engine for research tasks."""

    def __init__(self, task_id: str, prompt: str, context: str = ""):
        self.task_id = task_id
        self.prompt = prompt
        self.context = context
        self.knowledge_graph = KnowledgeGraph()
        self.status = "Inicializálás"
        self.current_thought = "Kutatási feladat inicializálása..."
        self.iteration = 0
        self.max_iterations = 20
        self.conversation_history = []

        # Initialize conversation with user prompt
        if context:
            self.conversation_history.append({
                'role': 'system',
                'content': f'Ön egy autonóm kutatóágens. Kiindulási kontextus:\n\n{context}'
            })

        self.conversation_history.append({
            'role': 'user',
            'content': f'Kutatási feladat: {prompt}'
        })

    def update_status(self, status: str, thought: str):
        """Update the current status and thought."""
        self.status = status
        self.current_thought = thought
        research_tasks[self.task_id]['status'] = status
        research_tasks[self.task_id]['current_thought'] = thought
        research_tasks[self.task_id]['entity_count'] = len(self.knowledge_graph.entities)

    def reasoning_phase(self) -> Dict:
        """
        Reasoning: Orchestrator decides next action based on current state.
        """
        self.update_status("Következtetés", "Az aktuális tudás elemzése és következő lépés meghatározása...")

        # Build reasoning prompt with knowledge graph
        kg_summary = self.knowledge_graph.to_text()

        reasoning_messages = self.conversation_history + [
            {
                'role': 'system',
                'content': f'''Ön egy autonóm kutatóágens kognitív magja. 

JELENLEGI TUDÁSGRÁF:
{kg_summary}

FELADAT:
1. Elemezze a felhasználói kutatási kérdést
2. Vizsgálja meg a jelenlegi tudásgráfot
3. Határozza meg a következő legfontosabb kutatási lépést
4. Válassza ki a megfelelő eszközt és paramétereket

Válaszoljon JSON formátumban:
{{
    "thought": "Az aktuális helyzet elemzése és következő lépés indoklása",
    "action": "next_action",
    "tool": "tool_name",
    "tool_params": {{}},
    "is_complete": false
}}

Ha úgy érzi, hogy elegendő információt gyűjtött, állítsa is_complete-et true-ra.'''
            }
        ]

        provider, model = select_model('reasoning')
        response = call_llm(provider, model, reasoning_messages, max_tokens=2000)

        try:
            # Parse JSON response
            decision = json.loads(response['content'])
            return decision
        except json.JSONDecodeError:
            # Fallback if LLM doesn't return valid JSON
            return {
                'thought': response['content'][:500],
                'action': 'search',
                'tool': 'exa_search',
                'tool_params': {'query': self.prompt[:100], 'num_results': 10},
                'is_complete': False
            }

    def action_phase(self, decision: Dict) -> Dict:
        """
        Action: Execute the decided tool with parameters.
        """
        tool_name = decision.get('tool', 'exa_search')
        tool_params = decision.get('tool_params', {})

        self.update_status("Cselekvés", f"Eszköz végrehajtása: {tool_name}...")

        if tool_name in TOOL_REGISTRY:
            try:
                result = TOOL_REGISTRY[tool_name](**tool_params)
                return result
            except Exception as e:
                return {'success': False, 'error': str(e)}
        else:
            return {'success': False, 'error': f'Unknown tool: {tool_name}'}

    def observation_phase(self, action_result: Dict) -> str:
        """
        Observation: Process the tool result and format it.
        """
        self.update_status("Megfigyelés", "Az eszköz eredményének feldolgozása...")

        if not action_result.get('success', False):
            return f"Hiba történt: {action_result.get('error', 'Ismeretlen hiba')}"

        # Format results based on type
        if 'results' in action_result:
            observation = f"Találatok száma: {len(action_result['results'])}\n\n"
            for i, result in enumerate(action_result['results'][:5], 1):
                observation += f"{i}. {result.get('title', 'Nincs cím')}\n"
                observation += f"   URL: {result.get('url', '')}\n"
                if result.get('published_date'):
                    observation += f"   Dátum: {result['published_date']}\n"
                observation += "\n"
        elif 'contents' in action_result:
            observation = f"Tartalmak száma: {len(action_result['contents'])}\n\n"
            for i, content in enumerate(action_result['contents'][:3], 1):
                observation += f"{i}. {content.get('title', 'Nincs cím')}\n"
                observation += f"   Szöveg előnézet: {content.get('text', '')[:500]}...\n\n"
        else:
            observation = json.dumps(action_result, indent=2, ensure_ascii=False)

        return observation

    def reflection_phase(self, decision: Dict, observation: str):
        """
        Reflection: Update knowledge graph with new information.
        """
        self.update_status("Reflexió", "Tudásgráf frissítése új információkkal...")

        # Simple entity and relation extraction
        # In a real system, this would use NLP or an LLM

        # Add decision thought as system note
        thought = decision.get('thought', '')

        # Extract entities from observation (simplified)
        # This is a placeholder - in production, use NER or LLM-based extraction
        lines = observation.split('\n')
        for line in lines:
            if 'URL:' in line:
                url = line.split('URL:')[1].strip()
                self.knowledge_graph.sources.add(url)

        # Update conversation history
        self.conversation_history.append({
            'role': 'assistant',
            'content': f"Gondolat: {thought}\n\nMegfigyelés:\n{observation}"
        })

    def run(self):
        """
        Main research loop: Reasoning -> Action -> Observation -> Reflection
        """
        try:
            self.update_status("Kutatás", "Autonóm kutatási ciklus indítása...")

            while self.iteration < self.max_iterations:
                self.iteration += 1

                # 1. Reasoning
                decision = self.reasoning_phase()

                # Check if research is complete
                if decision.get('is_complete', False):
                    self.update_status("Szintézis", "Kutatás befejezve, jelentés generálása...")
                    break

                # 2. Action
                action_result = self.action_phase(decision)

                # 3. Observation
                observation = self.observation_phase(action_result)

                # 4. Reflection
                self.reflection_phase(decision, observation)

                # Small delay to prevent rate limiting
                time.sleep(2)

            # Final synthesis
            self.synthesize_report()

        except Exception as e:
            self.update_status("Hiba", f"Kutatás megszakadt: {str(e)}")
            research_tasks[self.task_id]['error'] = str(e)
            research_tasks[self.task_id]['traceback'] = traceback.format_exc()

    def synthesize_report(self):
        """
        Generate final report using Claude for synthesis.
        """
        self.update_status("Szintézis", "Végső jelentés generálása...")

        kg_text = self.knowledge_graph.to_text()

        synthesis_prompt = f'''Ön egy oknyomozó újságíró. Az alábbi tudásgráf és kutatási eredmények alapján készítsen egy részletes, elemző jelentést.

EREDETI KUTATÁSI KÉRDÉS:
{self.prompt}

TUDÁSGRÁF ÉS EREDMÉNYEK:
{kg_text}

KUTATÁSI FOLYAMAT:
{json.dumps(self.conversation_history[-10:], indent=2, ensure_ascii=False)}

FELADAT:
Készítsen egy 20 oldalas, strukturált, Markdown formátumú jelentést, amely:
1. Összefoglalja a legfontosabb megállapításokat
2. Részletesen elemzi az entitásokat és kapcsolatokat
3. Táblázatokkal jeleníti meg az ellentmondásokat vagy összetett összefüggéseket
4. Minden állítást alátámaszt a tudásgráfban szereplő forrásokkal
5. Fejezetekre tagolt, világos szerkezetű

Használjon fejezet címeket (##), alcímeket (###), táblázatokat, és bullet pontokat a jobb olvashatóság érdekében.'''

        provider, model = select_model('final_report')

        response = call_llm(
            provider,
            model,
            [{'role': 'user', 'content': synthesis_prompt}],
            max_tokens=16000
        )

        final_report = response['content']

        # Save report
        research_tasks[self.task_id]['report'] = final_report
        research_tasks[self.task_id]['status'] = 'Befejezve'
        research_tasks[self.task_id]['current_thought'] = 'Kutatás sikeresen befejezve!'
        research_tasks[self.task_id]['completed_at'] = datetime.now().isoformat()


