@app.route('/')
def index():
    """Serve the main HTML page."""
    return send_file('index.html')


@app.route('/start_research', methods=['POST'])
def start_research():
    """
    Start a new research task.
    Expected JSON: {"prompt": "...", "context": "..."}
    """
    data = request.json
    prompt = data.get('prompt', '')
    context = data.get('context', '')

    if not prompt:
        return jsonify({'error': 'Prompt is required'}), 400

    # Generate task ID
    task_id = str(uuid.uuid4())

    # Initialize task storage
    research_tasks[task_id] = {
        'task_id': task_id,
        'prompt': prompt,
        'context': context,
        'status': 'Inicializálás',
        'current_thought': 'Feladat létrehozva, várakozás indításra...',
        'entity_count': 0,
        'created_at': datetime.now().isoformat(),
        'report': None,
        'error': None
    }

    # Start research in background thread
    orchestrator = ResearchOrchestrator(task_id, prompt, context)
    thread = threading.Thread(target=orchestrator.run, daemon=True)
    thread.start()

    return jsonify({
        'task_id': task_id,
        'message': 'Kutatás elindítva'
    })


@app.route('/status/<task_id>', methods=['GET'])
def get_status(task_id):
    """
    Get the status of a research task.
    """
    if task_id not in research_tasks:
        return jsonify({'error': 'Task not found'}), 404

    task = research_tasks[task_id]

    return jsonify({
        'task_id': task_id,
        'status': task['status'],
        'current_thought': task['current_thought'],
        'entity_count': task['entity_count'],
        'created_at': task['created_at'],
        'is_complete': task['status'] == 'Befejezve',
        'has_error': task.get('error') is not None
    })


@app.route('/report/<task_id>', methods=['GET'])
def get_report(task_id):
    """
    Get the final report for a completed task.
    """
    if task_id not in research_tasks:
        return jsonify({'error': 'Task not found'}), 404

    task = research_tasks[task_id]

    if task['status'] != 'Befejezve':
        return jsonify({'error': 'Task not completed yet'}), 400

    if not task['report']:
        return jsonify({'error': 'No report available'}), 404

    return jsonify({
        'task_id': task_id,
        'report': task['report'],
        'completed_at': task.get('completed_at'),
        'entity_count': task['entity_count']
    })


